macro_rules! decode_registered {
    ($payload:ident, $bytes:expr, $reader:expr) => {
        RegisteredEventEnvelope::$payload(crate::EventEnvelopeV1::<$payload>::decode_and_verify(
            $bytes, $reader,
        )?)
    };
}

/// Verifies and decodes a registered event selected by its trusted type/version pair.
///
/// Returns `Ok(None)` only when the integrity-verified pair is not compiled into
/// this reader; callers may then use the opaque-event admission path.
///
/// # Errors
///
/// Returns [`crate::EventIntegrityError`] for malformed, unreadable, tampered,
/// metadata-inconsistent, or schema-invalid registered event bytes.
pub fn decode_registered_event(
    bytes: &[u8],
    reader: crate::ProtocolVersion,
) -> Result<Option<RegisteredEventEnvelope>, crate::EventIntegrityError> {
    let metadata = crate::peek_verified_event_dispatch_metadata(bytes, reader)?;
    let event = match (metadata.event_type().as_str(), metadata.schema_version()) {
        ("agent.installation.changed.v1", 1) => {
            decode_registered!(AgentInstallationChangedV1, bytes, reader)
        }
        ("agent.binding.changed.v1", 1) => decode_registered!(AgentBindingChangedV1, bytes, reader),
        ("agent.grant.changed.v1", 1) => decode_registered!(AgentGrantChangedV1, bytes, reader),
        ("agent.consent.changed.v1", 1) => decode_registered!(AgentConsentChangedV1, bytes, reader),
        ("agent.approval.requested.v1", 1) => {
            decode_registered!(AgentApprovalRequestedV1, bytes, reader)
        }
        ("agent.approval.resolved.v1", 1) => {
            decode_registered!(AgentApprovalResolvedV1, bytes, reader)
        }
        ("host.observed.v1", 1) => decode_registered!(HostObservedV1, bytes, reader),
        ("connector.spec.changed.v1", 1) => {
            decode_registered!(ConnectorSpecChangedV1, bytes, reader)
        }
        ("connector.observed.v1", 1) => decode_registered!(ConnectorObservedV1, bytes, reader),
        ("agent.run.changed.v1", 1) => decode_registered!(AgentRunChangedV1, bytes, reader),
        ("job.changed.v1", 1) => decode_registered!(JobChangedV1, bytes, reader),
        ("job.step.changed.v1", 1) => decode_registered!(JobStepChangedV1, bytes, reader),
        ("job.evidence.changed.v1", 1) => decode_registered!(JobEvidenceChangedV1, bytes, reader),
        ("cloud.resource.changed.v1", 1) => {
            decode_registered!(CloudResourceChangedV1, bytes, reader)
        }
        ("service.changed.v1", 1) => decode_registered!(ServiceChangedV1, bytes, reader),
        ("service.operation.changed.v1", 1) => {
            decode_registered!(ServiceOperationChangedV1, bytes, reader)
        }
        ("directory.registration.changed.v1", 1) => {
            decode_registered!(DirectoryRegistrationChangedV1, bytes, reader)
        }
        _ => return Ok(None),
    };
    Ok(Some(event))
}
